// Parse LinkedIn and Instagram viral content
const items = $input.all();

let linkedinPosts = [];
let instagramPosts = [];

// Process LinkedIn response
try {
  const linkedinResponse = items[0]?.json;
  if (linkedinResponse?.content?.[0]?.text) {
    const text = linkedinResponse.content[0].text;
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      linkedinPosts = parsed.posts || [];
    }
  }
} catch (e) {
  console.log('LinkedIn parse error:', e.message);
}

// Process Instagram response
try {
  const instagramResponse = items[1]?.json;
  if (instagramResponse?.content?.[0]?.text) {
    const text = instagramResponse.content[0].text;
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      instagramPosts = parsed.posts || [];
    }
  }
} catch (e) {
  console.log('Instagram parse error:', e.message);
}

const today = new Date().toISOString().split('T')[0];
const output = [];

// Format LinkedIn posts
linkedinPosts.forEach((post, index) => {
  output.push({
    json: {
      date: today,
      platform: 'LinkedIn',
      variation: index + 1,
      formula: post.formula || 'N/A',
      hook: post.hook || '',
      full_post: post.full_post || '',
      hashtags: post.first_comment_hashtags || '',
      why_viral: post.why_viral || '',
      best_time: post.best_time_to_post || 'Tue-Thu 8-10am',
      status: 'Ready to Review'
    }
  });
});

// Format Instagram posts
instagramPosts.forEach((post, index) => {
  output.push({
    json: {
      date: today,
      platform: 'Instagram',
      variation: index + 1,
      format: post.format || 'N/A',
      hook: post.hook || '',
      visual_concept: post.visual_concept || '',
      caption: post.caption || '',
      hashtags: post.hashtags || '',
      why_viral: post.why_viral || '',
      content_pillar: post.content_pillar || '',
      status: 'Ready to Review'
    }
  });
});

return output.length > 0 ? output : [{ json: { error: 'No posts generated' } }];
